import boto3

def summarize_error_logs(log_events):
    client = boto3.client('logs', region_name='us-east-1')
    summary = {
        'total_errors': len(log_events),
        'error_messages': [log_event['message'] for log_event in log_events]
    }
    return summary

import re

def check_log_text_safety(log_text):
    unsafe_patterns = [r'password', r'secret', r'sensitive']
    for pattern in unsafe_patterns:
        if re.search(pattern, log_text, re.IGNORECASE):
            return False
    return True
